INSERT INTO taxonomy_domains (slug, name, description, position) VALUES
  ('safety', 'Safety', 'Working without getting hurt: the habits, protective equipment and hazard controls every job on a floor starts from.', 1),
  ('production', 'Production', 'What everyone on a floor shares: reading the print and the instruction, keeping lots traceable, working in controlled rooms, moving material and improving the work.', 2),
  ('machining', 'Machining', 'Cutting metal to size: manual and CNC machines, grinding, EDM, setup and programming.', 3),
  ('fabrication', 'Fabrication', 'Shaping and joining metal: welding, cutting, sheet metal, stamping and dies, die casting and additive manufacturing.', 4),
  ('materials', 'Materials', 'Changing what a material is or how its surface behaves: heat treatment, surface treatment, paint, composites and materials testing.', 5),
  ('assembly', 'Assembly', 'Putting hardware together: fastening, fits and alignment, and the assembly of machines, vehicles, aircraft, rocket engines and spacecraft.', 6),
  ('electronics', 'Electronics', 'Building electronics and wiring: soldering and board assembly, rework, harnesses and cabling, power electronics, servers and devices.', 7),
  ('semiconductor', 'Semiconductor', 'Making chips: lithography, deposition, etch, diffusion and implant, wafer metrology and defects, packaging, test and failure analysis.', 8),
  ('battery', 'Battery and electric drive', 'Making battery cells, modules and packs, and the electric motors and drive units they power.', 9),
  ('process', 'Process', 'Food, beverage and pharmaceutical processing: batching, filling, sterilization, aseptic work and laboratory analysis under GMP.', 10),
  ('quality', 'Quality', 'Measuring and assuring: measurement tools, inspection, coordinate metrology, calibration, statistics, corrective action and quality systems.', 11),
  ('ndt', 'Nondestructive testing', 'Finding flaws without harming the part: visual, penetrant, magnetic particle, ultrasonic, radiographic and eddy current methods.', 12),
  ('test', 'Test', 'Proving that a product works: electrical, functional, environmental, radio-frequency, vehicle and propulsion testing, and launch site operations.', 13),
  ('maintenance', 'Maintenance', 'Keeping machines and aircraft running: mechanical and electrical maintenance, fluid power, reliability methods, vacuum and utilities, and aircraft maintenance.', 14),
  ('automation', 'Automation', 'Making machines run themselves: instrumentation, PLCs, motion and drives, industrial networks, robots and machine vision.', 15),
  ('engineering', 'Engineering', 'Designing parts and the processes that make them: drawings and design data, CAD, design methods and manufacturing engineering.', 16);
INSERT INTO taxonomy_groups (slug, domain_slug, name, description, position) VALUES
  ('workplace-safety', 'safety', 'Workplace safety', 'The habits and protective equipment every person on a floor needs, and the training for work at height and in confined spaces.', 1),
  ('hazardous-energy', 'safety', 'Hazardous energy', 'Staying clear of the energy that injures: electricity, stored pressure, moving machines and robots, laser light and radiation.', 2),
  ('hazardous-materials', 'safety', 'Hazardous materials', 'Handling chemicals, dusts, process gases and explosives so nobody is exposed and nothing spills, burns or goes off.', 3),
  ('shop-basics', 'production', 'Shop basics', 'Reading what the job calls for: the drawing, the written instruction and the arithmetic between them.', 4),
  ('lot-control', 'production', 'Lot control', 'Keeping every lot tied to its recipe, materials and history as it moves through the plant.', 5),
  ('controlled-environments', 'production', 'Controlled environments', 'Working in rooms where particles and static are the enemy: gowning, cleanroom conduct and electrostatic discharge control.', 6),
  ('foreign-object-control', 'production', 'Foreign object control', 'Keeping loose hardware, debris and tools out of flight hardware.', 7),
  ('material-handling', 'production', 'Material handling', 'Lifting and moving loads with trucks, cranes and rigging.', 8),
  ('continuous-improvement', 'production', 'Continuous improvement', 'The lean and Six Sigma methods a plant uses to organize an area, standardize the work, measure its losses and remove them.', 9),
  ('manual-machining', 'machining', 'Manual machining', 'Making a part by hand on the engine lathe and the knee mill, the machines a machinist learns first.', 10),
  ('cnc-setup', 'machining', 'CNC setup', 'Getting a CNC machine ready to cut and keeping it on size: the control, offsets, workholding, speeds and feeds.', 11),
  ('cnc-machining', 'machining', 'CNC machining', 'Running machining centers and lathes, from three-axis milling to multi-axis, Swiss-type and large aerospace and casting work.', 12),
  ('grinding', 'machining', 'Grinding', 'Finishing hardened parts to size and surface with abrasives: precision grinding, wheel dressing, honing, lapping and jig grinding.', 13),
  ('electrical-discharge-machining', 'machining', 'Electrical discharge machining', 'Cutting hardened metal with a spark, by wire or by shaped electrode.', 14),
  ('cnc-programming', 'machining', 'CNC programming', 'Writing the program a CNC machine runs: G-code by hand, toolpaths in CAM software, and proving them in simulation.', 15),
  ('arc-welding', 'fabrication', 'Arc welding', 'Reading the weld symbol, fitting the joint and welding it by MIG, stick, flux-cored and TIG, up to pipe and orbital work.', 16),
  ('alloy-welding', 'fabrication', 'Alloy welding', 'Welding the metals that punish mistakes: stainless steel, aluminum, titanium and aluminum-lithium.', 17),
  ('resistance-welding', 'fabrication', 'Resistance welding', 'Spot welding sheet by hand gun, pedestal or robot, and keeping the electrodes in condition.', 18),
  ('beam-and-friction-welding', 'fabrication', 'Beam and friction welding', 'Machine welding without an arc: laser welding and brazing, friction stir and electron beam.', 19),
  ('weld-quality', 'fabrication', 'Weld quality', 'Proving a weld and the people and procedures behind it: visual inspection, destructive tests and qualification to a code.', 20),
  ('cutting-processes', 'fabrication', 'Cutting processes', 'Cutting plate and sheet to shape by flame, plasma, laser and waterjet.', 21),
  ('sheet-metal-work', 'fabrication', 'Sheet metal work', 'Laying out, bending and forming sheet, plate and tube into finished shapes.', 22),
  ('heavy-fabrication', 'fabrication', 'Heavy fabrication', 'Fitting and welding plate, beams and shells into structures, tanks and pressure vessels.', 23),
  ('stamping-and-dies', 'fabrication', 'Stamping and dies', 'Running presses and the dies in them, from operating and setting a die to fitting, spotting and trying one out.', 24),
  ('die-casting', 'fabrication', 'Die casting', 'Casting aluminum under pressure: the melt, the machine and its die, the spray, the shot and the trim.', 25),
  ('additive-manufacturing', 'fabrication', 'Additive manufacturing', 'Printing parts in metal and polymer: handling the powder, preparing and running the build and finishing what comes out.', 26),
  ('heat-treatment', 'materials', 'Heat treatment', 'Changing a metal''s hardness and structure in a furnace: relieving stress, annealing, hardening, case hardening, vacuum and pressure cycles.', 27),
  ('age-hardening', 'materials', 'Age hardening', 'Bringing aluminum, titanium and nickel alloys to temper by solution treatment, quench and aging.', 28),
  ('furnace-pyrometry', 'materials', 'Furnace pyrometry', 'Proving that a furnace or autoclave measures and holds the temperature it claims.', 29),
  ('materials-testing', 'materials', 'Materials testing', 'Testing what a material has become: hardness, strength and structure under the microscope.', 30),
  ('surface-treatment', 'materials', 'Surface treatment', 'Treating metal in chemical and electrolytic baths: conversion coating, passivation, anodizing, electropolishing and plating.', 31),
  ('paint-pretreatment', 'materials', 'Paint pretreatment', 'Getting a surface ready to hold paint: stripping and blasting, phosphate conversion and electrocoat primer.', 32),
  ('paint-application', 'materials', 'Paint application', 'Putting paint and sealer on: masking, sealing seams, spraying by gun and by robot, matching color and repairing defects.', 33),
  ('coating-inspection', 'materials', 'Coating inspection', 'Checking a coating once it is on: thickness, defects, appearance and adhesion.', 34),
  ('composite-fabrication', 'materials', 'Composite fabrication', 'Building a laminate: cutting and kitting plies, preparing the tool, laying up, infusing, and trimming the cured part.', 35),
  ('composite-curing', 'materials', 'Composite curing', 'Bagging a layup and curing it in an autoclave or oven, from thermocouple placement to writing and controlling the cycle.', 36),
  ('composite-bonding', 'materials', 'Composite bonding', 'Joining composite and metal details with adhesive: surface preparation, film and paste adhesives, secondary bonds and co-cure.', 37),
  ('composite-repair', 'materials', 'Composite repair', 'Assessing damage in composite structure and restoring it by bonded or bolted repair.', 38),
  ('assembly-practice', 'assembly', 'Assembly practice', 'What every assembler does at a station: hand and torque tools, securing fasteners, checking the build and reworking it.', 39),
  ('precision-mechanical-assembly', 'assembly', 'Precision mechanical assembly', 'Fitting bearings and interference fits and balancing what rotates.', 40),
  ('machine-tool-building', 'assembly', 'Machine tool building', 'Building a machine tool and making it accurate: guides, ballscrews and spindles, scraping and alignment, then measuring and compensating its errors.', 41),
  ('structural-fastening', 'assembly', 'Structural fastening', 'Fastening aircraft structure: knowing the fastener, preparing the hole and installing rivets, pins, lockbolts and nutplates.', 42),
  ('airframe-assembly', 'assembly', 'Airframe assembly', 'Building an airframe: sealing and shimming joints, installing skins, lines and control surfaces, joining major sections and rigging the controls.', 43),
  ('vehicle-body-assembly', 'assembly', 'Vehicle body assembly', 'Building a vehicle body from stamped panels: mechanical joining, structural adhesive, hemming, framing and fitting closures.', 44),
  ('vehicle-final-assembly', 'assembly', 'Vehicle final assembly', 'The stations of a vehicle''s final line, from routing the harness to marrying the powertrain and filling the fluids.', 45),
  ('rocket-engine-build', 'assembly', 'Rocket engine build', 'Making and assembling a liquid rocket engine: injectors and cooling channels, valves and turbopumps, the engine itself and its refurbishment.', 46),
  ('launch-vehicle-integration', 'assembly', 'Launch vehicle integration', 'Installing the tanks, pressure vessels, steering and separation hardware of a launch vehicle, and mating the sections of a missile.', 47),
  ('spacecraft-integration', 'assembly', 'Spacecraft integration', 'Building a satellite or spacecraft: structure and units, insulation, thrusters, fluid loops and the mechanisms that deploy.', 48),
  ('recovery-and-reuse', 'assembly', 'Recovery and reuse', 'The hardware that brings a vehicle back and the inspection that lets it fly again: heat shield tiles, parachutes and post-flight inspection.', 49),
  ('soldering-and-rework', 'electronics', 'Soldering and rework', 'Soldering by hand to the IPC standards, judging the joint, finding the failed part and replacing it.', 50),
  ('board-assembly-line', 'electronics', 'Board assembly line', 'Running and programming the machines that build a circuit board: paste printing, placement, reflow, wave soldering and automatic inspection.', 51),
  ('coating-and-potting', 'electronics', 'Coating and potting', 'Protecting a finished circuit with conformal coating or resin.', 52),
  ('cable-and-harness-assembly', 'electronics', 'Cable and harness assembly', 'Building wiring: crimping and terminating wire, assembling connectors and harnesses, securing bundles, bonding and grounding, coaxial and fiber cables.', 53),
  ('electronics-cooling', 'electronics', 'Electronics cooling', 'Getting heat out of electronics: thermal interface materials, heat sinks, cold plates and coolant loops.', 54),
  ('power-electronics', 'electronics', 'Power electronics', 'Building inverters, converters and the power semiconductor modules inside them.', 55),
  ('server-integration', 'electronics', 'Server integration', 'Building servers and racks: installing components, mounting and cabling the rack, then configuring firmware, storage and the operating system.', 56),
  ('consumer-device-assembly', 'electronics', 'Consumer device assembly', 'Assembling phones, laptops and similar devices: battery, display, camera, seals and sensor calibration.', 57),
  ('communication-terminals', 'electronics', 'Communication terminals', 'Building the radio and laser terminals that carry data to and between satellites.', 58),
  ('contamination-control', 'semiconductor', 'Contamination control', 'Handling wafers without damaging or contaminating them, and counting the particles a room, a liquid or a tool adds.', 59),
  ('lithography', 'semiconductor', 'Lithography', 'Printing the circuit pattern: resist coat, exposure and develop, immersion and EUV scanners, process windows and mask correction.', 60),
  ('thin-film-deposition', 'semiconductor', 'Thin film deposition', 'Putting films on a wafer from gases and sputter targets: CVD, PVD, epitaxy and atomic layer deposition.', 61),
  ('plasma-etch', 'semiconductor', 'Plasma etch', 'Transferring the pattern into the film with a reactive plasma and stopping at the right layer.', 62),
  ('wet-processing', 'semiconductor', 'Wet processing', 'Cleaning, etching, stripping and polishing wafers with liquid chemistry and slurry.', 63),
  ('diffusion-and-implant', 'semiconductor', 'Diffusion and implant', 'Growing oxide, annealing and doping wafers in furnaces, lamp tools and implanters.', 64),
  ('wafer-metrology', 'semiconductor', 'Wafer metrology', 'Measuring what the process made on the wafer: line width, overlay, film thickness, sheet resistance and stress.', 65),
  ('defect-and-yield', 'semiconductor', 'Defect and yield', 'Finding defects on wafers, naming them and tracing them, with tool sensor data, back to the step that caused them.', 66),
  ('chip-packaging', 'semiconductor', 'Chip packaging', 'Turning a finished wafer into packaged devices: dicing, die attach, wire and flip chip bonding, underfill and molding.', 67),
  ('probe-and-final-test', 'semiconductor', 'Probe and final test', 'Testing every die on the wafer and every packaged device electrically.', 68),
  ('failure-analysis', 'semiconductor', 'Failure analysis', 'Finding the physical cause of a failed chip: fault isolation, cross-sections, electron microscopy samples and depth profiles.', 69),
  ('electrode-manufacturing', 'battery', 'Electrode manufacturing', 'Making the electrode: mixing slurry, coating and drying it on foil, calendering and slitting.', 70),
  ('cell-assembly', 'battery', 'Cell assembly', 'Building the cell in the dry room: winding or stacking, tab welding, insertion, electrolyte fill and sealing.', 71),
  ('cell-finishing', 'battery', 'Cell finishing', 'Bringing a sealed cell to life and sorting it: formation, degassing, aging, voltage checks and grading.', 72),
  ('module-and-pack-assembly', 'battery', 'Module and pack assembly', 'Building cells into modules and packs: interconnects and busbars, cooling, high-voltage wiring, management electronics and sealing.', 73),
  ('electric-motor-build', 'battery', 'Electric motor build', 'Building a traction motor: winding or hairpin stators, impregnation, rotor magnets, housing and final assembly.', 74),
  ('pack-and-motor-testing', 'battery', 'Pack and motor testing', 'Proving a finished pack or drive unit at the end of the line: leak tests and the electrical and performance tests.', 75),
  ('gmp-and-sanitation', 'process', 'GMP and sanitation', 'Working the way a regulated plant must: good manufacturing practice, food safety controls, cleaning and sanitizing, and proving a process by validation.', 76),
  ('food-processing', 'process', 'Food processing', 'Making food and beverage product: measuring, batching and blending, carbonating and drying.', 77),
  ('sterilization', 'process', 'Sterilization', 'Killing organisms in product and on devices with heat or gas: pasteurizing, retorting, steam and ethylene oxide.', 78),
  ('filling-and-packaging', 'process', 'Filling and packaging', 'Filling and closing containers and running the packaging line and its in-line checks.', 79),
  ('tablet-manufacturing', 'process', 'Tablet manufacturing', 'Making solid-dose drug product: granulating and blending, compressing and coating tablets.', 80),
  ('aseptic-processing', 'process', 'Aseptic processing', 'Making sterile product without contaminating it: qualified gowning, aseptic technique, filling and freeze drying.', 81),
  ('laboratory-analysis', 'process', 'Laboratory analysis', 'The quality control laboratory''s chemical and microbiological tests on product, water and the manufacturing environment.', 82),
  ('measurement-tools', 'quality', 'Measurement tools', 'The instruments an inspector or machinist measures a part with, from calipers and micrometers to gauge blocks, profilometers and comparators.', 83),
  ('part-inspection', 'quality', 'Part inspection', 'Inspecting parts against the drawing: reading its geometric tolerances, checking in process, sampling a lot, the first article and the record.', 84),
  ('coordinate-metrology', 'quality', 'Coordinate metrology', 'Measuring in three dimensions against the model: coordinate measuring machines, scanners and laser trackers.', 85),
  ('calibration', 'quality', 'Calibration', 'Checking measuring instruments against traceable standards and stating how far a measurement can be trusted.', 86),
  ('statistical-methods', 'quality', 'Statistical methods', 'Using data to control and understand a process: control charts, capability, measurement system studies and designed experiments.', 87),
  ('corrective-action', 'quality', 'Corrective action', 'From the nonconforming part to the cause removed: reporting, disposition, root cause, 8D and corrective action.', 88),
  ('quality-planning', 'quality', 'Quality planning', 'Planning quality into a process before it runs: failure mode analysis, the control plan and the approval package.', 89),
  ('quality-system-standards', 'quality', 'Quality system standards', 'Knowing what a quality management standard requires and working and auditing to it.', 90),
  ('visual-methods', 'ndt', 'Visual methods', 'Examining a surface by eye, directly or through a borescope.', 91),
  ('penetrant-methods', 'ndt', 'Penetrant methods', 'Finding surface-breaking flaws with liquid penetrant: the removal methods, developers, fluorescent inspection and the checks that keep a line valid.', 92),
  ('magnetic-particle-methods', 'ndt', 'Magnetic particle methods', 'Finding surface and near-surface flaws in steel by magnetizing it: yoke, coil and head shot techniques, wet and dry particles, field verification and demagnetizing.', 93),
  ('ultrasonic-basics', 'ndt', 'Ultrasonic basics', 'Setting up an ultrasonic instrument and reading it: the A-scan, calibration on reference blocks, thickness and the choice of transducer.', 94),
  ('ultrasonic-techniques', 'ndt', 'Ultrasonic techniques', 'Inspecting with sound: straight and angle beam, contact and immersion, through-transmission and C-scan, sizing flaws and inspecting welds.', 95),
  ('phased-array-and-tofd', 'ndt', 'Phased array and TOFD', 'Ultrasonic imaging with arrays and encoded scans: phased array, full matrix capture and time-of-flight diffraction.', 96),
  ('radiographic-methods', 'ndt', 'Radiographic methods', 'Making a radiograph on film and reading it: exposure, image quality indicators, scatter control, processing and interpretation of welds and castings.', 97),
  ('digital-x-ray-methods', 'ndt', 'Digital X-ray methods', 'Radiography without film: phosphor plates, flat-panel detectors, real-time cells and computed tomography.', 98),
  ('eddy-current-methods', 'ndt', 'Eddy current methods', 'Finding cracks and measuring conductivity with induced currents: probes, the impedance plane, lift-off, bolt holes, aircraft structure and arrays.', 99),
  ('composite-inspection', 'ndt', 'Composite inspection', 'Finding disbonds, delaminations, porosity and impact damage in composite and bonded structure.', 100),
  ('ndt-procedure-development', 'ndt', 'NDT procedure development', 'The Level III work behind an inspection: writing the procedure and designing the reference standard it is calibrated on.', 101),
  ('electrical-test', 'test', 'Electrical test', 'Measuring and proving circuits with bench instruments: the multimeter and oscilloscope, continuity and high-voltage insulation tests.', 102),
  ('functional-test', 'test', 'Functional test', 'Running a product through its functional test and building the fixtures and programs that test it.', 103),
  ('data-bus-testing', 'test', 'Data bus testing', 'Checking the data buses that link the electronic units of a vehicle or aircraft.', 104),
  ('rf-test', 'test', 'RF test', 'Measuring radio-frequency hardware: spectrum and network analyzers, electromagnetic compatibility and radar.', 105),
  ('environmental-testing', 'test', 'Environmental testing', 'Stressing a product with heat, vibration, vacuum and time to prove it survives and to learn how long it will last.', 106),
  ('vehicle-end-of-line-testing', 'test', 'Vehicle end-of-line testing', 'The checks a finished vehicle passes before it leaves the plant: alignment, lamps, driver-assistance sensors, rolls, water, noises and final inspection.', 107),
  ('propulsion-testing', 'test', 'Propulsion testing', 'Running motors and engines on a stand or dynamometer and reading the data they produce.', 108),
  ('launch-site-operations', 'test', 'Launch site operations', 'Ground operations at a test stand or launch pad: cryogenic propellants, couplings and umbilicals, loading, and raising the vehicle.', 109),
  ('equipment-maintenance', 'maintenance', 'Equipment maintenance', 'Keeping production machines running: scheduled upkeep, conveyors, pumps and gearboxes, leveling and alignment, and finding why a tool has stopped.', 110),
  ('electrical-maintenance', 'maintenance', 'Electrical maintenance', 'The plant electrician''s work: reading the schematic, wiring and testing motors, running conduit, troubleshooting motor controls and working on 480 V power.', 111),
  ('fluid-power', 'maintenance', 'Fluid power', 'Hydraulics and pneumatics: reading the circuit, servicing and repairing components, then testing and troubleshooting the system.', 112),
  ('reliability-methods', 'maintenance', 'Reliability methods', 'Maintaining by condition and by the numbers: thermography, oil and vibration analysis, and reliability metrics.', 113),
  ('vacuum-and-utilities', 'maintenance', 'Vacuum and utilities', 'Running vacuum systems and finding their leaks, and the ultrapure water a fab depends on.', 114),
  ('aircraft-maintenance', 'maintenance', 'Aircraft maintenance', 'Servicing an aircraft''s systems to its maintenance manual, running its engines and signing the work off.', 115),
  ('aircraft-structural-repair', 'maintenance', 'Aircraft structural repair', 'Repairing aircraft structure to the manufacturer''s manual: corrosion treatment and sheet metal repair.', 116),
  ('instrumentation', 'automation', 'Instrumentation', 'The sensors and transmitters a control system reads: finding them on the diagram, wiring them and calibrating them.', 117),
  ('plc-programming', 'automation', 'PLC programming', 'Programming and troubleshooting the controllers that run a machine, and the operator screens that go with them.', 118),
  ('motion-and-drives', 'automation', 'Motion and drives', 'Setting up the drives that turn motors and axes, and tuning servo loops.', 119),
  ('industrial-networks', 'automation', 'Industrial networks', 'The networks that tie controllers, drives and plant software together.', 120),
  ('robot-programming', 'automation', 'Robot programming', 'Running and programming industrial robots: the teach pendant, end-of-arm tooling, each maker''s language and offline simulation.', 121),
  ('robot-cell-engineering', 'automation', 'Robot cell engineering', 'Designing a robot cell: its tooling, its layout and the safeguarding that lets people work near it.', 122),
  ('machine-vision', 'automation', 'Machine vision', 'Making a camera system see a part reliably and programming it to find, measure and inspect.', 123),
  ('design-documentation', 'engineering', 'Design documentation', 'The drawing, the assembly model and the controlled data a shop builds from.', 124),
  ('cad-software', 'engineering', 'CAD software', 'Modeling parts and making drawings in the CAD systems manufacturers use.', 125),
  ('design-methods', 'engineering', 'Design methods', 'The analysis behind a design: manufacturability, tolerance stacks, failure modes, additive design and finite element analysis.', 126),
  ('manufacturing-engineering', 'engineering', 'Manufacturing engineering', 'Designing how the work is done: instructions, time standards, balanced lines and error-proof stations.', 127);
